/**
 * HTTP client for playground eval batches (`/v1/dev/evals/runs`).
 *
 * Used by `agent-sdk eval --prod` (or `--url`) so the batch runs on the serve
 * process and is mirrored to `defineStorage` when an `evals` table is
 * configured. Without those flags, eval keeps the in-process ephemeral path
 * in `cli-ax.ts`.
 */
import { expandSummarySuiteSelection, isEvalSummaryCase, matchesEvalIdFilter, } from "../evals.js";
import { stopIfDryRun } from "./dry-run.js";
import { isRecord } from "./is-record.js";
import { mergeRequestHeaders } from "./request-headers.js";
const DEFAULT_POLL_MS = 1_000;
const EVAL_BATCH_STATUSES = ["running", "completed", "failed", "cancelled"];
async function responseJson(resp) {
    try {
        return await resp.json();
    }
    catch {
        return {};
    }
}
function isEvalRunSnapshot(value) {
    if (!isRecord(value) || !isRecord(value.summary) || !isRecord(value.config)) {
        return false;
    }
    if (!Array.isArray(value.cases)) {
        return false;
    }
    return (typeof value.runId === "string" &&
        typeof value.startedAt === "string" &&
        EVAL_BATCH_STATUSES.some((status) => status === value.status) &&
        typeof value.summary.passed === "number" &&
        typeof value.summary.failed === "number" &&
        typeof value.summary.total === "number" &&
        typeof value.summary.done === "number");
}
function snapshotOrThrow(value, message, code) {
    if (!isEvalRunSnapshot(value)) {
        throw new RemoteEvalError(message, undefined, code);
    }
    return value;
}
export class RemoteEvalError extends Error {
    constructor(message, status, code, activeRunId) {
        super(message);
        this.status = status;
        this.code = code;
        this.activeRunId = activeRunId;
        this.name = "RemoteEvalError";
    }
}
/**
 * Start a batch on the target serve via `POST /v1/dev/evals/runs`, poll until
 * terminal, and return CLI-shaped case results.
 */
export async function runRemoteEvals(options) {
    const baseUrl = options.baseUrl.replace(/\/$/, "");
    const fetchImpl = options.fetchImpl ?? fetch;
    const auth = {
        bearerToken: options.bearerToken,
        headers: options.headers,
    };
    const started = await startRemoteEvalRun({
        baseUrl,
        auth,
        fetchImpl,
        filterIds: options.filterIds,
        tags: options.tags,
        timeoutMs: options.timeoutMs,
        verbose: options.verbose,
        signal: options.signal,
    });
    options.onSnapshot?.(started);
    const snapshot = await pollRemoteEvalRun({
        baseUrl,
        runId: started.runId,
        auth,
        fetchImpl,
        pollMs: options.pollMs ?? DEFAULT_POLL_MS,
        signal: options.signal,
        onSnapshot: options.onSnapshot,
    });
    return { snapshot, results: snapshotToEvalRunResults(snapshot) };
}
/** List datapoints from `GET /v1/dev/evals` (same surface a remote run uses). */
export async function listRemoteEvals(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    let resp;
    try {
        resp = await fetchImpl(`${baseUrl}/v1/dev/evals`, {
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
    }
    catch (error) {
        throw new RemoteEvalError(error instanceof Error ? error.message : "Could not list evals.", undefined, "start_failed");
    }
    if (!resp.ok) {
        throw new RemoteEvalError(`Could not list evals (HTTP ${resp.status}).`, resp.status, "start_failed");
    }
    const parsed = await responseJson(resp);
    const body = isRecord(parsed) ? parsed : {};
    const listed = [];
    const rows = Array.isArray(body.evals) ? body.evals : [];
    for (const rowValue of rows) {
        if (!isRecord(rowValue)) {
            continue;
        }
        const row = rowValue;
        if (typeof row.id !== "string" || row.id === "") {
            continue;
        }
        if (typeof row.fileId !== "string" || row.fileId === "") {
            continue;
        }
        const tags = Array.isArray(row.tags)
            ? row.tags.filter((t) => typeof t === "string")
            : undefined;
        listed.push({
            id: row.id,
            fileId: row.fileId,
            ...(typeof row.description === "string" ? { description: row.description } : {}),
            ...(tags === undefined || tags.length === 0 ? {} : { tags }),
        });
    }
    let selected = listed;
    if (args.filterIds !== undefined && args.filterIds.length > 0) {
        selected = selected.filter((e) => args.filterIds.some((f) => matchesEvalIdFilter(e.id, f)));
    }
    if (args.tags !== undefined && args.tags.length > 0) {
        selected = selected.filter((e) => (e.tags ?? []).some((t) => args.tags.includes(t)));
    }
    // Match server-side filterDiscoveredEvals: summary → whole file.
    return expandSummarySuiteSelection(listed, selected, (e) => isEvalSummaryCase(e.tags));
}
export async function startRemoteEvalRun(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    const body = {};
    if (args.filterIds !== undefined && args.filterIds.length > 0) {
        body.filterIds = args.filterIds;
    }
    if (args.tags !== undefined && args.tags.length > 0) {
        body.tags = args.tags;
    }
    if (args.timeoutMs !== undefined) {
        body.timeoutMs = args.timeoutMs;
    }
    if (args.verbose === true) {
        body.verbose = true;
    }
    stopIfDryRun({ method: "POST", path: `${baseUrl}/v1/dev/evals/runs`, body });
    let resp;
    try {
        resp = await fetchImpl(`${baseUrl}/v1/dev/evals/runs`, {
            method: "POST",
            headers: {
                "content-type": "application/json",
                ...mergeRequestHeaders(args.auth),
            },
            body: JSON.stringify(body),
            signal: args.signal,
        });
    }
    catch (error) {
        throw new RemoteEvalError(error instanceof Error ? error.message : "Could not start eval run.", undefined, "start_failed");
    }
    const parsed = await responseJson(resp);
    const json = isRecord(parsed) ? parsed : {};
    if (json.error === "no_matching_evals") {
        throw new RemoteEvalError("No matching evals found.", 404, "no_matching_evals");
    }
    if (resp.status === 409 || json.error === "eval_run_in_progress") {
        const activeRunId = typeof json.activeRunId === "string" && json.activeRunId !== ""
            ? json.activeRunId
            : undefined;
        throw new RemoteEvalError(activeRunId !== undefined
            ? `An eval run is already in progress (${activeRunId}).`
            : "An eval run is already in progress.", 409, "eval_run_in_progress", activeRunId);
    }
    if (!resp.ok) {
        const detail = typeof json.message === "string" && json.message !== ""
            ? json.message
            : typeof json.error === "string" && json.error !== ""
                ? json.error
                : `HTTP ${resp.status}`;
        throw new RemoteEvalError(`Could not start eval run: ${detail}`, resp.status, "start_failed");
    }
    if (typeof json.runId !== "string" || json.runId === "") {
        throw new RemoteEvalError("Eval start response missing runId.", undefined, "start_failed");
    }
    return snapshotOrThrow(parsed, "Eval start response missing runId.", "start_failed");
}
/** Cancel a running batch via `POST /v1/dev/evals/runs/:runId/cancel`. */
export async function cancelRemoteEvalRun(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    const cancelUrl = `${baseUrl}/v1/dev/evals/runs/${encodeURIComponent(args.runId)}/cancel`;
    stopIfDryRun({ method: "POST", path: cancelUrl });
    let resp;
    try {
        resp = await fetchImpl(cancelUrl, {
            method: "POST",
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
    }
    catch (error) {
        throw new RemoteEvalError(error instanceof Error ? error.message : "Could not cancel eval run.", undefined, "cancel_failed");
    }
    const parsed = await responseJson(resp);
    const json = isRecord(parsed) ? parsed : {};
    if (resp.status === 404 || json.error === "unknown_eval_run") {
        throw new RemoteEvalError(`Unknown eval run ${args.runId}.`, 404, "unknown_eval_run");
    }
    if (resp.status === 409 || json.error === "eval_run_not_running") {
        const status = typeof json.status === "string" && json.status !== "" ? json.status : "unknown";
        throw new RemoteEvalError(typeof json.message === "string" && json.message !== ""
            ? json.message
            : `Eval run ${args.runId} is not running (status: ${status}).`, 409, "eval_run_not_running");
    }
    if (!resp.ok) {
        const detail = typeof json.message === "string" && json.message !== ""
            ? json.message
            : typeof json.error === "string" && json.error !== ""
                ? json.error
                : `HTTP ${resp.status}`;
        throw new RemoteEvalError(`Could not cancel eval run: ${detail}`, resp.status, "cancel_failed");
    }
    if (typeof json.runId !== "string" || json.runId === "") {
        throw new RemoteEvalError("Eval cancel response missing runId.", undefined, "cancel_failed");
    }
    return snapshotOrThrow(parsed, "Eval cancel response missing runId.", "cancel_failed");
}
/** One-shot `GET /v1/dev/evals/runs/:runId` (no polling). */
export async function getRemoteEvalRun(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    let resp;
    try {
        resp = await fetchImpl(`${baseUrl}/v1/dev/evals/runs/${encodeURIComponent(args.runId)}`, {
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
    }
    catch (error) {
        throw new RemoteEvalError(error instanceof Error ? error.message : "Could not fetch eval run.", undefined, "poll_failed");
    }
    if (resp.status === 404) {
        throw new RemoteEvalError(`Unknown eval run ${args.runId}.`, 404, "unknown_eval_run");
    }
    if (!resp.ok) {
        throw new RemoteEvalError(`Could not fetch eval run (HTTP ${resp.status}).`, resp.status, "poll_failed");
    }
    return snapshotOrThrow(await responseJson(resp), "Could not fetch eval run.", "poll_failed");
}
/** Recent batches from `GET /v1/dev/evals/runs`. */
export async function listRemoteEvalRuns(args) {
    const baseUrl = args.baseUrl.replace(/\/$/, "");
    const fetchImpl = args.fetchImpl ?? fetch;
    let resp;
    try {
        resp = await fetchImpl(`${baseUrl}/v1/dev/evals/runs`, {
            headers: mergeRequestHeaders(args.auth),
            signal: args.signal,
        });
    }
    catch (error) {
        throw new RemoteEvalError(error instanceof Error ? error.message : "Could not list eval runs.", undefined, "poll_failed");
    }
    if (!resp.ok) {
        throw new RemoteEvalError(`Could not list eval runs (HTTP ${resp.status}).`, resp.status, "poll_failed");
    }
    const parsed = await responseJson(resp);
    const body = isRecord(parsed) ? parsed : {};
    const runs = Array.isArray(body.runs) ? body.runs.filter(isEvalRunSnapshot) : [];
    return {
        runs,
        ...(typeof body.activeRunId === "string" && body.activeRunId !== ""
            ? { activeRunId: body.activeRunId }
            : {}),
    };
}
export async function pollRemoteEvalRun(args) {
    const pollMs = args.pollMs ?? DEFAULT_POLL_MS;
    let lastJson = "";
    for (;;) {
        if (args.signal?.aborted === true) {
            throw new RemoteEvalError("Eval wait aborted.", undefined, "aborted");
        }
        const snap = await getRemoteEvalRun(args);
        const serialized = JSON.stringify(snap);
        if (serialized !== lastJson) {
            lastJson = serialized;
            args.onSnapshot?.(snap);
        }
        if (snap.status !== "running") {
            return snap;
        }
        await sleep(pollMs, args.signal);
    }
}
export function snapshotToEvalRunResults(snapshot) {
    return snapshot.cases.map((c) => ({
        id: c.id,
        path: c.fileId,
        ...(c.description === undefined ? {} : { description: c.description }),
        ok: c.ok === true,
        // Older serve processes send no verdict; infer it from `ok` so a remote
        // batch still prints and reports consistently.
        verdict: c.verdict ?? (c.ok === true ? "passed" : "failed"),
        ...(c.skipReason === undefined ? {} : { skipReason: c.skipReason }),
        ...(c.metadata === undefined ? {} : { metadata: c.metadata }),
        assertions: c.assertions ?? [],
        ...(c.sessionId === undefined ? {} : { sessionId: c.sessionId }),
        inputs: c.inputs ?? [],
        ...(c.finalText === undefined ? {} : { finalText: c.finalText }),
        ...(c.tools === undefined ? {} : { tools: c.tools }),
        ...(c.toolCalls === undefined ? {} : { toolCalls: c.toolCalls }),
        ...(c.error === undefined ? {} : { error: c.error }),
        logs: c.logs ?? [],
        metrics: c.metrics ?? {},
        durationMs: c.durationMs ?? 0,
    }));
}
function sleep(ms, signal) {
    return new Promise((resolve, reject) => {
        if (signal?.aborted === true) {
            reject(new RemoteEvalError("Eval wait aborted.", undefined, "aborted"));
            return;
        }
        const timer = setTimeout(() => {
            signal?.removeEventListener("abort", onAbort);
            resolve();
        }, ms);
        const onAbort = () => {
            clearTimeout(timer);
            reject(new RemoteEvalError("Eval wait aborted.", undefined, "aborted"));
        };
        signal?.addEventListener("abort", onAbort, { once: true });
    });
}
